/* @lc app=leetcode id=3850 lang=kotlin */ class Solution { fun ev(x: Int): List<Int> = listOf(if (x == 2 || x == 6) 1 else if (x == 4) 2 else 0, if (x == 3 || x == 6) 1 else 0, if (x == 5) 1 else 0) fun cnt(k: Long, p: Long): Pair<Int, Long> = generateSequence(0 to k) { (c, r) -> if (r % p == 0L) c + 1 to r / p else null }.last() fun countSequences(nums: IntArray, k: Long): Int = cnt(k, 2).let { (a, r1) -> cnt(r1, 3).let { (b, r2) -> cnt(r2, 5).let { (c, r3) -> if (r3 != 1L) 0 else nums.fold(mapOf(Triple(0, 0, 0) to 1L)) { cur, x -> ev(x).let { e -> HashMap<Triple<Int, Int, Int>, Long>().also { nx -> cur.forEach { (s, w) -> listOf(0, 1, -1).forEach { sg -> nx.merge(Triple(s.first + sg * e[0], s.second + sg * e[1], s.third + sg * e[2]), w) { p, q -> p + q } } } } } }[Triple(a, b, c)]?.toInt() ?: 0 } } } }